Definition PF_TABPTR : Z := 0x809c0.   (* [comment removed for export] *)
Definition PF_TAB : Z := 0x15c56.      (* [comment removed for export] *)

(* [comment removed for export] *)
Definition oPP (sp : word) : Z := bv_unsigned sp + 40.
Definition oBF (sp : word) : Z := bv_unsigned sp + 48.
Definition oVL (sp : word) : Z := bv_unsigned sp + 4152.
Definition oNM (sp : word) : Z := bv_unsigned sp + 4168.

Definition pf_fail (E' : ecv) : Prop :=
  ec_cat E' = G_HTTP_CAT /\ ec_failed E' = true /\ ec_ok E' /\ 2 <= ec_flags E'
  /\ In (ec_val E') [HE_NEED_MORE; HE_HEADER_LIMIT; HE_BAD_LINE_ENDING; HE_BAD_FIELD; HE_BAD_VALUE].

(* [comment removed for export] *)
Definition pf_succ (p0 L vb p' nlen vptr vlen bsz : Z) : Prop :=
  p0 + 2 <= p' /\ p' + 1 <= L /\ 1 <= nlen /\ p0 + nlen < p'
  /\ p0 + nlen + 3 <= p' /\ 0 <= vlen /\ nlen + vlen + 3 <= p' - p0
  /\ ((p0 <= vptr /\ 0 <= vlen /\ vptr + vlen <= p') \/ (vptr = vb /\ vlen = bsz)).

Definition pf_out (E0 E' : ecv) (p0 L vb p' : Z) (n1 n2 v1 v2 : word) (bsz : Z) : Prop :=
  (E' = E0 /\ exists nlen vptr vlen, n1 = wz p0 /\ n2 = wz nlen /\ v1 = wz vptr /\ v2 = wz vlen
                /\ pf_succ p0 L vb p' nlen vptr vlen bsz)
  \/ pf_fail E'.

Section HCW.
  Context {HCEIL : HeapCeil}.

Definition PfTab (m : mem) : Prop := rw_cells rsegs m PF_TABPTR [C8 (wz PF_TAB)].

Lemma PfTab_transport : forall W m m', PfTab m -> munch W m m' -> wmono rsegs m m' ->
  Forall (fun iv : Z * Z => PF_TABPTR + 8 <= fst iv \/ snd iv <= PF_TABPTR) W -> PfTab m'.
Proof.
  intros W m m' T MU WM FW. unfold PfTab in *. eapply rw_cells_transport; [exact T | exact MU | exact WM |].
  cbn [cells_size csize Nat.add]. clear T MU WM. induction W as [|[lo hi] W IH]; [exact I|].
  pose proof (Forall_inv FW) as H1. cbn in H1. cbn. split; [lia|]. apply IH. exact (Forall_inv_tail FW).
Qed.

Definition pf_W (lo : Z) (sp : word) (E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + 4184); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition pf_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' p' E' g' (n1 n2 v1 v2 : word) bsz bb,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (pf_W lo sp E) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' (oPP sp) [C8 (wz p')]
    /\ rw_cells rsegs m' (oNM sp) [C8 n1; C8 n2]
    /\ rw_cells rsegs m' (oVL sp) [C8 v1; C8 v2]
    /\ rw_cells rsegs m' (oBF sp) [C8 (wz bsz); CB 4096 bb] /\ 0 <= bsz <= 4096
    /\ rw_cells rsegs m' E (ErrCodeCells E')
    /\ bytes_at rsegs m' p0 bs /\ PfTab m'
    /\ pf_out E0 E' p0 (p0 + Z.of_nat (length bs)) (oBF sp + 8) p' n1 n2 v1 v2 bsz
    /\ HttpCat m' g' /\ XStatics m'.

Definition pf_pure (sp : word) (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) : Prop :=
  ec_ok E0 /\ ec_failed E0 = false /\ lo + 224 <= bv_unsigned sp /\ 0xb4000 <= lo
  /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0x90d70 <= p0) /\ p0 + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp + 4184 <= E /\ E + 24 <= 2^64.

Definition pf_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) (g : bool)
    (nm0 vl0 : list byte) (bsz0 : Z) (bb0 : list byte),
  rw_cells rsegs m (oPP sp) [C8 (wz p0)] ->
  rw_cells rsegs m (oNM sp) [CB 16 nm0] ->
  rw_cells rsegs m (oVL sp) [CB 16 vl0] ->
  rw_cells rsegs m (oBF sp) [C8 (wz bsz0); CB 4096 bb0] -> 0 <= bsz0 <= 4096 ->
  rw_cells rsegs m E (ErrCodeCells E0) ->
  bytes_at rsegs m p0 bs -> PfTab m ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) ->
  pf_pure sp E lo p0 bs E0 ->
  mem_inv rsegs m ->
  evt rsegs (pf_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc E lo p0 bs E0 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (oPP sp)) (wz (p0 + Z.of_nat (length bs))) (wz (oNM sp)) (wz (oVL sp))
              (wz (oBF sp)) (wz E) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_FIELD) fc None m (seg_rom rsegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition pf_ctx (m m1 : mem) (sp : word) (sv : list word) (E L lo : Z) (p0 : Z) (bs : list byte)
    (sl : word) (tl : list byte) (tmp : list cell) (pv : Z) (n1 n2 v1 v2 : word) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool)
  : Prop :=
  rw_cells rsegs m1 (bv_unsigned sp + -144) [C8 sl]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -136) [CB 8 tl]
  /\ rw_cells rsegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells rsegs m1 (bv_unsigned sp + -104) (map C8 sv)
  /\ rw_cells rsegs m1 (bv_unsigned sp + 40) [C8 (wz pv)]
  /\ rw_cells rsegs m1 (bv_unsigned sp + 4168) [C8 n1; C8 n2]
  /\ rw_cells rsegs m1 (bv_unsigned sp + 4152) [C8 v1; C8 v2]
  /\ rw_cells rsegs m1 (bv_unsigned sp + 48) [C8 (wz bsz); CB 4096 bb]
  /\ rw_cells rsegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ bytes_at rsegs m1 p0 bs /\ L = p0 + Z.of_nat (length bs) /\ rw_cells rsegs m1 526784 [C8 (wz 89174)]
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk rsegs m1 lo (bv_unsigned sp + -144)
  /\ munch (pf_W lo sp E) m m1 /\ wmono rsegs m m1 /\ mem_inv rsegs m1.

(* [comment removed for export] *)
Definition pf_sv (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) : list word :=
  [s11; s10; s9; s8; s7; s6; s5; s4; s3; s2; s1; s0; ra].

(* [comment removed for export] *)
Definition pf_purei (sp : word) (E lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv) : Prop :=
  pf_pure sp E lo p0 bs E0 /\ 0 <= bv_unsigned sp /\ bv_unsigned sp + 4184 <= 2^64.

Local Ltac pf_finish p' E' g' n1 n2 v1 v2 bsz bb :=
  apply evt_done; unfold pf_post, oPP, oNM, oVL, oBF, PfTab, PF_TABPTR, PF_TAB;
  do 16 eexists; exists p', E', g', n1, n2, v1, v2, bsz, bb;
  split; [reflexivity|]; repeat match goal with |- _ /\ _ => split end; try fast_assumption; try lia.
