Lemma rw_cells_C8_CB8 : forall m A (w : word), rw_cells rsegs m A [C8 w] -> rw_cells rsegs m A [CB 8 (le8 w)].
Proof.
  intros m A w H. eapply rw_cells_reshape; [exact H | cbn; split; [apply (length_le8 w) | exact I] | cbn [cells_bytes cbytes]; reflexivity].
Qed.

