(* [comment removed for export] *)
Definition pf_exitT_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a7 s2x s5x s6x s7x s8x s9x s10x s11x
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (E L lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (sl : word) (tl junk : list byte) (pv q : Z) (n1 n2 v1 v2 : word) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool),
  pf_ctx m m1 sp (pf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) E L lo p0 bs
         sl tl [CB 24 junk] pv n1 n2 v1 v2 bsz bb e1 e2 e3 g ->
  pf_purei sp E lo p0 bs E0 -> 0 <= bsz <= 4096 -> 0 <= q < 2^64 ->
  evt rsegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc E lo p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz q) a0 a1 a2 a3 a4 a5 (wz 0x7c080) a7
              s2x (Z_to_bv 64 (bv_unsigned sp + 40)) (wz L) s5x s6x s7x s8x s9x s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

Local Ltac pf_exitT_script e loc :=
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a7 s2x s5x s6x s7x s8x s9x s10x s11x
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
         F fc m m1 E L lo p0 bs E0 sl tl junk pv q n1 n2 v1 v2 bsz bb e1 e2 e3 g;
  intros CTX PURE BSZ QR;
  destruct CTX as (SL & TL & TMP & FRhi & PPC & NMC & VLC & BFC & EC & WIN & LL & TB & HC & XS & ST & MU & WM & MI);
  destruct PURE as ((EOK & EF0 & LO & IMG & QLO & QHI & ELO & EHI) & SP0 & SPH);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold pf_W, G_HTTP_CAT in *; unfold pf_sv in FRhi; cbn [map] in FRhi;
  unfold wz in *;
  (* [comment removed for export] *)
  steps_to 0x323cc%Z;
  call_assignA_with (bv_unsigned sp + -144) (bv_unsigned sp + -128) e lo g junk;
  clear HC XS;
  lazymatch goal with
  | TMP' : rw_cells _ ?mx (bv_unsigned sp + -128) (ErrCodeCells _), HC : HttpCat _ true, XS : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP';
    (* [comment removed for export] *)
    do 40 (lazymatch goal with
           | |- evt _ _ (MS _ _ (Z_to_bv 64 0x3b1c8) _ _ _ _) => idtac
           | |- evt _ _ (MS _ _ (Z_to_bv 64 0x3b2d4) _ _ _ _) => idtac
           | |- evt _ _ _ => go1 end);
    expose_statics HC XS [(E, E + 24); (bv_unsigned sp + 40, bv_unsigned sp + 48)]%Z;
    st1; st1; st1;
    (* [comment removed for export] *)
    steps_to 0x3b1d4%Z; st1; steps_to 0x3b38c%Z;
    do 13 step;
    join_frame TMP' FRhi (bv_unsigned sp + -128); join_frame TL TMP' (bv_unsigned sp + -136); join_frame SL TL (bv_unsigned sp + -144);
    step; release_frame SL ST' (bv_unsigned sp); step;
    lazymatch goal with
    | MU2 : munch _ mx ?my, WM2 : wmono _ mx ?my, PPC' : rw_cells _ ?my (bv_unsigned sp + 40) [C8 (Z_to_bv 64 ?p')] |- _ =>
        pf_finish p' (EC_http_loc e loc) true n1 n2 v1 v2 bsz bb;
        [ right; apply pf_fail_exit; [cbn; qtauto | reflexivity | lia | lia]
        | close_HttpCat_chunks
        | close_XStatics XS MU2 WM2 ]
